// GPU probe: sends a fixed GP0 command stream (gp0_stream.h, generated by
// gen_stream.py) once through the GP0 port, then idles.
//
// Observable contract:
//   g_probe_magic = 0x47505531 ("GPU1") once the whole stream has been sent.
//   VRAM then holds the result; nothing else is drawn afterwards.
#include "gp0_stream.h"
#include "psyqo/application.hh"
#include "psyqo/gpu.hh"
#include "psyqo/scene.hh"

extern "C" {
volatile uint32_t g_probe_magic = 0;
}

namespace {

class Probe final : public psyqo::Application {
    void prepare() override;
    void createScene() override;
};

class ProbeScene final : public psyqo::Scene {
    void frame() override;
    bool m_done = false;
};

Probe probe;
ProbeScene scene;

}  // namespace

void Probe::prepare() {
    psyqo::GPU::Configuration config;
    config.set(psyqo::GPU::Resolution::W640)
        .set(psyqo::GPU::VideoMode::AUTO)
        .set(psyqo::GPU::ColorMode::C15BITS)
        .set(psyqo::GPU::Interlace::INTERLACED);
    gpu().initialize(config);
}

void Probe::createScene() { pushScene(&scene); }

void ProbeScene::frame() {
    if (m_done) return;
    m_done = true;
    const uint32_t* p = g_gp0_stream;
    while (uint32_t n = *p++) {
        probe.gpu().waitReady();
        for (uint32_t i = 0; i < n; i++) psyqo::GPU::sendRaw(*p++);
    }
    g_probe_magic = 0x47505531;
}

int main() { return probe.run(); }
